/* Copyright (C) 2026 Rance Quest modding fork
 *
 * rq.ids: the game's numbers by name (loader 1.15.0). All of it is Lua: lua/ids.lua is
 * generated by tools/ids/gen_ids.py from data/ids, and this file only runs it.
 */

#ifdef RQ_MODLOADER

#include "lua.h"
#include "lauxlib.h"
#include "modloader.h"
#include "modloader_priv.h"

extern const char rq_ids_lua[];
extern const unsigned rq_ids_lua_len;

void rq_ids_open(lua_State *L, int rq_index)
{
	if (luaL_loadbuffer(L, rq_ids_lua, rq_ids_lua_len, "=ids") != LUA_OK) {
		rq_log("ids: %s", lua_tostring(L, -1));
		lua_pop(L, 1);
		return;
	}
	lua_pushvalue(L, rq_index);
	if (lua_pcall(L, 1, 0, 0) != LUA_OK) {
		rq_log("ids: %s", lua_tostring(L, -1));
		lua_pop(L, 1);
	}
}

#endif /* RQ_MODLOADER */
